<?php
namespace App\Filament\Resources\AssessmentSheets;
use App\Filament\Resources\AssessmentSheets\Pages; use App\Models\AssessmentSheet; use Filament\Actions\EditAction; use Filament\Forms\Components\DatePicker; use Filament\Forms\Components\Select; use Filament\Forms\Components\TextInput; use Filament\Resources\Resource; use Filament\Schemas\Schema; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Filters\SelectFilter; use Filament\Tables\Table;
class AssessmentSheetResource extends Resource {
 protected static ?string $model=AssessmentSheet::class; protected static ?string $modelLabel='ведомость'; protected static ?string $pluralModelLabel='Ведомости'; protected static string|\UnitEnum|null $navigationGroup='Контроль успеваемости';
 public static function form(Schema $s): Schema{return $s->components([
  Select::make('study_group_id')->label('Группа')->relationship('group','name')->required()->searchable()->preload(),Select::make('discipline_id')->label('Дисциплина')->relationship('discipline','name')->required()->searchable()->preload(),Select::make('teacher_id')->label('Преподаватель')->relationship('teacher','last_name')->searchable()->preload(),
  TextInput::make('academic_year')->label('Учебный год')->required(),TextInput::make('semester')->label('Семестр'),Select::make('control_type')->label('Форма контроля')->options(['credit'=>'Зачёт','differentiated_credit'=>'Дифференцированный зачёт','exam'=>'Экзамен','coursework'=>'Курсовая работа','practice'=>'Практика'])->required(),DatePicker::make('assessment_date')->label('Дата'),TextInput::make('number')->label('Номер ведомости'),Select::make('status')->label('Статус')->options(['draft'=>'Черновик','open'=>'Открыта','closed'=>'Закрыта'])->default('draft')->required()
 ]);}
 public static function table(Table $t): Table{return $t->columns([TextColumn::make('number')->label('№')->searchable(),TextColumn::make('assessment_date')->label('Дата')->date('d.m.Y')->sortable(),TextColumn::make('group.name')->label('Группа')->searchable(),TextColumn::make('discipline.name')->label('Дисциплина')->searchable()->wrap(),TextColumn::make('control_type')->label('Контроль')->badge(),TextColumn::make('status')->label('Статус')->badge()])->filters([SelectFilter::make('status')->label('Статус')->options(['draft'=>'Черновик','open'=>'Открыта','closed'=>'Закрыта'])])->recordActions([EditAction::make()]);}
 public static function getPages(): array{return ['index'=>Pages\ListAssessmentSheets::route('/'),'create'=>Pages\CreateAssessmentSheet::route('/create'),'edit'=>Pages\EditAssessmentSheet::route('/{record}/edit')];}
}